class StablePriorityQueue
  def initialize
    @items = []
    @counter = 0
  end

  def push(priority, item)
    @items << { priority: priority, order: @counter, item: item }
    @counter += 1
    @items = @items.sort_by { |i| [i[:priority], i[:order]] }
  end

  def pop
    @items.shift[:item]
  end

  def size
    @items.size
  end
end

